using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    // Technical (I/O, HTTP, serialization, persistence) namespaces the business layers must not touch.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Text.Json", "System.Data",
        "System.Diagnostics.Process", "Microsoft.Extensions", "Microsoft.EntityFrameworkCore",
    ];

    public static TheoryData<string, Assembly, string[]> Rules => new()
    {
        { "Domain -> Application/Infrastructure", typeof(Money).Assembly, [ApplicationNs, InfrastructureNs] },
        { "Domain -> technical", typeof(Money).Assembly, TechnicalNamespaces },
        { "Application -> Infrastructure", typeof(AuthorizePayment).Assembly, [InfrastructureNs] },
        { "Application -> technical", typeof(AuthorizePayment).Assembly, TechnicalNamespaces },
    };

    [Theory]
    [MemberData(nameof(Rules))]
    public void Layer_does_not_depend_on_forbidden_namespaces(string rule, Assembly assembly, string[] forbidden)
    {
        var result = Types.InAssembly(assembly)
            .ShouldNot().HaveDependencyOnAny(forbidden)
            .GetResult();

        Assert.True(result.IsSuccessful,
            $"{rule} violated by: {string.Join(", ", result.FailingTypeNames ?? [])}");
    }

    [Fact]
    public void Infrastructure_assembly_is_the_one_holding_technical_adapters()
    {
        Assert.NotEmpty(Types.InAssembly(typeof(HttpPaymentGateway).Assembly).That().ResideInNamespace(InfrastructureNs).GetTypes());
    }
}
